// Get the USGS earthquake data from the previous node
const usgsData = $input.all();

// Extract features array from the response
const features = usgsData[0].json.features || [];

// Map each earthquake to normalized format matching backend model
const normalizedData = features.map(earthquake => {
  const props = earthquake.properties;
  const coords = earthquake.geometry.coordinates;

  // Convert magnitude to severity string
  let severity = "low";
  if (props.mag >= 6.0) severity = "high";
  else if (props.mag >= 4.5) severity = "moderate";

  return {
    json: {
      source: "usgs",
      event_type: "earthquake",
      title: props.place || `M ${props.mag} Earthquake`,
      description: `Magnitude: ${props.mag}, Depth: ${coords[2]}km`,
      latitude: coords[1],
      longitude: coords[0],
      magnitude: props.mag,
      severity: severity,
      event_time: new Date(props.time).toISOString()
    }
  };
});

return normalizedData;

// Parse XML from GDACS API and normalize disaster data
const inputData = $input.all();
const normalizedItems = [];

for (const item of inputData) {
  const xmlData = item.json;

  let disasters = [];

  if (xmlData.rss && xmlData.rss.channel && xmlData.rss.channel.item) {
    disasters = Array.isArray(xmlData.rss.channel.item) 
      ? xmlData.rss.channel.item 
      : [xmlData.rss.channel.item];
  }

  for (const disaster of disasters) {
    // Extract coordinates
    let latitude = null;
    let longitude = null;

    if (disaster['georss:point']) {
      const coords = disaster['georss:point'].split(' ');
      latitude = parseFloat(coords[0]);
      longitude = parseFloat(coords[1]);
    } else if (disaster['geo:lat'] && disaster['geo:long']) {
      latitude = parseFloat(disaster['geo:lat']);
      longitude = parseFloat(disaster['geo:long']);
    }

    // Extract disaster type
    let disasterType = 'unknown';
    if (disaster.category) {
      const category = disaster.category.toLowerCase();
      if (category.includes('earthquake')) disasterType = 'earthquake';
      else if (category.includes('flood')) disasterType = 'flood';
      else if (category.includes('cyclone') || category.includes('hurricane')) disasterType = 'cyclone';
      else if (category.includes('volcano')) disasterType = 'volcano';
      else if (category.includes('drought')) disasterType = 'drought';
      else if (category.includes('wildfire') || category.includes('fire')) disasterType = 'wildfire';
    }

    // Extract severity
    let severity = 'unknown';
    if (disaster['gdacs:severity']) {
      severity = disaster['gdacs:severity'];
    } else if (disaster['gdacs:alertlevel']) {
      severity = disaster['gdacs:alertlevel'];
    }

    normalizedItems.push({
      json: {
        source: "gdacs",
        event_type: disasterType,
        title: disaster.title || 'Unknown Disaster',
        description: disaster.description || '',
        latitude: latitude,
        longitude: longitude,
        magnitude: null, // GDACS doesn't provide magnitude
        severity: severity,
        event_time: disaster.pubDate || new Date().toISOString()
      }
    });
  }
}

return normalizedItems;

// Normalize OpenAQ v3 air quality data
const inputData = $input.all();
const normalizedData = [];

for (const item of inputData) {
  const results = item.json.results || [];

  for (const location of results) {
    const locationName = location.name || location.location || 'Unknown Location';
    const latitude = location.coordinates?.latitude || null;
    const longitude = location.coordinates?.longitude || null;

    const latestMeasurements = location.measurements || location.latest || [];

    for (const measurement of latestMeasurements) {
      normalizedData.push({
        json: {
          source: "openaq",
          location: locationName,
          parameter: measurement.parameter || 'unknown',
          value: measurement.value || 0,
          unit: measurement.unit || 'µg/m³',
          latitude: latitude,
          longitude: longitude,
          measured_at: measurement.lastUpdated || measurement.datetime || new Date().toISOString()
        }
      });
    }
  }
}

return normalizedData;
